import{_ as d,o as t,c as o,a2 as s}from"./chunks/framework.DMvgf4hZ.js";const u=JSON.parse('{"title":"本地开发与构建","description":"","frontmatter":{},"headers":[],"relativePath":"development/setup.md","filePath":"development/setup.md","lastUpdated":1794885765000}'),a={name:"development/setup.md"};function n(i,e,c,r,l,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="本地开发与构建" tabindex="-1">本地开发与构建 <a class="header-anchor" href="#本地开发与构建" aria-label="Permalink to &quot;本地开发与构建&quot;">​</a></h1><h2 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to &quot;本地开发&quot;">​</a></h2><p>先安装 Git 和项目指定版本的 <a href="https://bun.sh/" target="_blank" rel="noreferrer">Bun</a>，然后执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dolfly/toonflow.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toonflow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>公开仓 <code>dolfly/toonflow</code> 只镜像上游 <code>HBAI-Ltd/Toonflow-app</code> 的代码；本项目的 fork 改造源码在私有仓 <code>Scenoria/toonflow</code>，需要向维护者申请访问权限。</p><p>首次开发或修改插件后，构建节点和工具并同步到 <code>data/</code>，再启动 Web 与业务 Server：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 首次开发或修改插件后，构建节点和工具并同步到 data/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:plugins</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 同时启动 Web 与业务 Server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <code>http://localhost:5173</code>。独立 Server 默认监听 <code>3000</code>，Web 开发服务会代理 API 请求。<code>dev</code> 不会自动构建或同步插件，因此首次启动需要上面的 <code>dev:plugins</code> 步骤。</p><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><p>以下命令在仓库根目录执行：</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>bun run dev:web</code></td><td>单独启动 Web 开发服务。</td></tr><tr><td><code>bun run dev:server</code></td><td>单独启动业务 Server。</td></tr><tr><td><code>bun run dev:plugins</code></td><td>构建节点和工具，并同步到开发数据目录。</td></tr><tr><td><code>bun run dev:desktop</code></td><td>同步开发插件、构建 Web，并启动桌面应用。</td></tr><tr><td><code>bun run build</code></td><td>构建工具、Web、Server、MCP，并输出技能和提供方文件。</td></tr><tr><td><code>bun run build:server</code></td><td>构建独立部署所需的节点、工具、Web、Server、MCP、技能和提供方，支持 Linux。</td></tr><tr><td><code>bun run build:nodes</code></td><td>构建节点到 <code>build/nodes/</code>，不写入 <code>data/nodes/</code>。</td></tr><tr><td><code>bun run build:tools</code></td><td>构建默认工具到 <code>build/tools/</code>，不写入 <code>data/tools/</code>；不包含可选的插件开发套件。</td></tr><tr><td><code>bun run start:server</code></td><td>运行 <code>build/server/</code> 中已构建的服务。</td></tr><tr><td><code>bun run build:desktop</code></td><td>构建当前平台的桌面应用及随包资源。</td></tr><tr><td><code>bun run package:desktop</code></td><td>生成当前平台的 Windows NSIS、macOS DMG 或 Linux DEB 安装包。</td></tr><tr><td><code>bun run release:desktop &lt;版本号&gt; --auto</code></td><td>生成当前平台安装包、完整更新包，并在存在上一版时生成 patch。</td></tr><tr><td><code>bun run typecheck</code></td><td>单独执行各工作区的类型检查。</td></tr><tr><td><code>bun run --cwd packages/i18n extract</code></td><td>手动抽取中文源文案和来源索引，不生成其他语言的译文。</td></tr></tbody></table><p>构建与类型检查分别执行。新增、移动或删除业务接口后，在 <code>apps/server</code> 执行 <code>bun run routes</code> 生成路由。</p><p>Windows 桌面日志位于安装目录的 <code>app/bin/app.log</code>。桌面 JavaScript 日志、初始化与依赖加载异常追加到同一文件，保留错误堆栈；启动助手也记录异常退出码。日志采用追加写入，日志不可写时仍保留控制台输出和启动失败提示。</p><p>插件开发工具位于 <code>packages/tools/pluginDeveloper</code>，作为工作区子包随默认工具构建和内置，产物为 <code>build/tools/pluginDeveloper.tool.js</code>，开发构建同步到 <code>data/tools/</code>。SDK 下载、缓存和插件构建由工具负责，主程序只提供本机权限校验及安装、刷新、上传桥接。工具私有资源在卸载时一并清理。</p><h2 id="云端渠道" tabindex="-1">云端渠道 <a class="header-anchor" href="#云端渠道" aria-label="Permalink to &quot;云端渠道&quot;">​</a></h2><p>账号、插件市场、余额统计、探索、首页广告和供应商 TS 的调用链为：页面直接请求本地 <code>/api/channel/*</code> → 后端 <code>Channel</code> 接口 → <code>Toonflow</code> 实现。前端只保留通用 HTTP 工具，不维护渠道抽象。外网地址、响应转换和供应商 TS 临时实现统一放在 <code>apps/server/src/utils/channel/toonflow.ts</code>，前后端共享的纯类型通过 <code>@toonflow/server/channel</code> 导出。</p><p>首页广告请求 <code>GET /api/channel/community/getAdvertisements</code>，经渠道转发至正式接口 <code>POST https://api.toonflow.net/web/toonflow/home/getAdvertisements</code>（<code>/web</code> 是部署代理前缀）。配置入口位于 API 管理后台侧栏“首页广告设置”（<code>/homeAdvertisement</code>），读取和保存分别使用管理员服务的 <code>POST /homeAdvertisement/getSettings</code>、<code>POST /homeAdvertisement/saveSettings</code>，图片通过 <code>POST /homeAdvertisement/getUploadSignature</code> 获取直传签名。客户端渠道仅公开读取广告，不转发管理员写入接口。服务端过滤停用和到期广告，返回 <code>banners</code>、<code>bannerMode</code>（<code>carousel</code> 轮换或 <code>stack</code> 叠加）、<code>bannerInterval</code>（2–60 秒，默认 5）及 <code>sidebar</code>；旧 <code>banner</code> 字段保留首条可见横幅。旧接口缺少 <code>banners</code> 时客户端兼容单条配置，明确的空数组不回退。首次部署按 API 管理员服务的迁移文档初始化广告表；构建不会自动执行数据库迁移。</p><p>顶部最多配置 10 条横幅，沿用现有广告表的 <code>banner.items</code> JSON 保存 <code>{ items, mode, interval }</code>，并镜像首条到旧字段；已有单横幅配置自动兼容，无需增加数据库字段。文字横幅最低 44px，正文支持行内 Markdown、回车换行和自动折行，高度随内容撑开；轮换跟随当前条目高度，叠加按顺序显示，每条可独立关闭。后台保存配置后刷新 Toonflow 首页即可读取；正常使用不要添加 <code>advertisementPreview</code> 参数。</p><p>本地 API 联调可直接请求管理服务 <code>62487</code> 和主服务 <code>62477</code>；主 API 设置 <code>ENABLE_BACKGROUND_JOBS=false</code>，关闭定时任务及视频、图片回调消费。Toonflow 广告读取统一使用正式地址，已移除临时本地接口覆盖，避免开发配置遮蔽线上已保存的广告。</p><p>开发环境仍可通过 <code>/#/home?advertisementPreview=text</code>、<code>image</code>、<code>web</code>、<code>carousel</code> 或 <code>stack</code> 显式查看临时示例；普通首页与生产构建均使用真实接口，接口失败时不回退到示例。</p><p>后端环境变量 <code>TOONFLOW_CHANNEL</code> 选择渠道，默认 <code>toonflow</code>。新增渠道时，实现 <code>utils/channel/types.ts</code> 中的 <code>Channel</code>，在 <code>utils/channel/index.ts</code> 注册实例，然后设置对应的渠道名称并重启后端；前端和业务路由无需修改。未注册的渠道会明确报错，不会回退到其他渠道。</p><p>鉴权请求使用服务端设置中保存的账号 Token，并核对前端携带的账号快照；渠道实例不保存可变 Token。供应商 TS 接口暂时返回空模型配置，真实接口就绪后替换 <code>Toonflow.getProviderSource</code>。</p><h2 id="构建后在本机运行-web-与-server" tabindex="-1">构建后在本机运行 Web 与 Server <a class="header-anchor" href="#构建后在本机运行-web-与-server" aria-label="Permalink to &quot;构建后在本机运行 Web 与 Server&quot;">​</a></h2><p>首次从源码运行，完成依赖安装后执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:server</span></span></code></pre></div><p>然后打开 <code>http://localhost:3000</code>。这套命令使用仓库根目录的默认 <code>data/</code>；服务首次启动会从构建产物初始化内置节点、工具、技能和提供方，保留已有插件文件。迁移到其他目录或机器时，需一并处理运行依赖、配置和工作区，不能只复制 <code>build/</code> 就视作完整安装。</p><p>独立 Server 采用单进程运行。桌面端复用同一个 <code>createApp</code>，在主进程监听系统分配的本机端口。目录选择、原生保存与桌面更新等接口仅由桌面宿主提供。</p><p>服务器部署、systemd 托管与数据目录说明见<a href="/toonflow/deploy/">服务端部署</a>。</p>`,28)])])}const k=d(a,[["render",n]]);export{u as __pageData,k as default};
